    TextBox ClassicTimeBox(string value)=>new(){Text=value,Dock=DockStyle.Fill,BackColor=Color.Black,ForeColor=Color.Lime,Font=new Font(Font,FontStyle.Bold),TextAlign=HorizontalAlignment.Center};
    void AddClassicDialogRow(TableLayoutPanel p,int row,string label,Control c){p.Controls.Add(new Label{Text=label,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft},0,row);p.Controls.Add(c,1,row);}
    DateTime ClassicDateTime(DateTime date,string time){if(!DateTime.TryParseExact(time.Trim(),"HH:mm",CultureInfo.InvariantCulture,DateTimeStyles.None,out var t))throw new Exception("Saat HH:mm biçiminde olmalı.");return date.Date.Add(t.TimeOfDay);}
    static bool IsAnnualLeave(string? value)=>string.Equals(value?.Trim(),"YILLIK İZİN",StringComparison.OrdinalIgnoreCase);
