    void ShowPaymentClassic()
    {
        if(currentPk=="")return;var pd=PeriodDates(periodO);using var d=new Form{Text="Maaş ve Mesai Ödemesi",StartPosition=FormStartPosition.CenterParent,Size=new Size(390,310),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,Font=Font};var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=8,Padding=new Padding(14)};p.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,145));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));
        var normal=new TextBox{Dock=DockStyle.Fill};var mesai=new TextBox{Dock=DockStyle.Fill};var nd=new DateTimePicker{Dock=DockStyle.Fill,Format=DateTimePickerFormat.Short};var md=new DateTimePicker{Dock=DockStyle.Fill,Format=DateTimePickerFormat.Short};AddClassicDialogRow(p,0,"Kart Numarası",new TextBox{Text=currentPk,ReadOnly=true,Dock=DockStyle.Fill});AddClassicDialogRow(p,1,"Personel",new TextBox{Text=(f.GetValueOrDefault("AD")?.Text+" "+f.GetValueOrDefault("SOYAD")?.Text).Trim(),ReadOnly=true,Dock=DockStyle.Fill});AddClassicDialogRow(p,2,"Dönem",new TextBox{Text=$"{pd.A:dd.MM.yyyy} - {pd.B:dd.MM.yyyy}",ReadOnly=true,Dock=DockStyle.Fill});AddClassicDialogRow(p,3,"Ödenen Maaş",normal);AddClassicDialogRow(p,4,"Maaş Ödeme Tarihi",nd);AddClassicDialogRow(p,5,"Ödenen Mesai",mesai);AddClassicDialogRow(p,6,"Mesai Ödeme Tarihi",md);
        try{var q=Q("select first 1 NODENEN,NOTARIH,FMODENEN,FMOTARIH from ODEME where PKNO=@PK and BASTAR=@A and BITTAR=@B",new FbParameter("@PK",currentPk),new FbParameter("@A",pd.A),new FbParameter("@B",pd.B));if(q.Rows.Count>0){var r=q.Rows[0];normal.Text=r["NODENEN"]==DBNull.Value?"":Convert.ToDecimal(r["NODENEN"]).ToString("0.00");mesai.Text=r["FMODENEN"]==DBNull.Value?"":Convert.ToDecimal(r["FMODENEN"]).ToString("0.00");if(r["NOTARIH"] is DateTime a)nd.Value=a;if(r["FMOTARIH"] is DateTime b)md.Value=b;}}catch{}
