    }

    DataTable LoadAllDialogPeople()=>Q("select K.PKNO,K.AD,K.SOYAD,K.ICTARIH,coalesce((select AD from GRUP G where G.KOD=K.GRUP),'') GRUPAD,coalesce((select AD from BOLUM B where B.KOD=K.BOLUM),'') BOLUMAD,coalesce((select AD from SERVIS S where S.KOD=K.SERVIS),'') SERVISAD,coalesce((select AD from DURUM D where D.KOD=K.DURUM),'') DURUMAD,coalesce((select AD from GOREV R where R.KOD=K.GOREV),'') GOREVAD,coalesce((select AD from FIRMA F where F.KOD=K.SIRKET),'') FIRMAAD from KIMLIK K order by K.PKNO");
    void FilterIzinPeople(DataTable t,ComboBox[] boxes,DataGridView left,int mode){string[] cols={"GRUPAD","BOLUMAD","SERVISAD","DURUMAD","GOREVAD","FIRMAAD"};var parts=new List<string>();for(int x=0;x<boxes.Length;x++)if(boxes[x].SelectedIndex>0)parts.Add(cols[x]+"='"+boxes[x].Text.Replace("'","''")+"'");if(mode==1)parts.Add("ICTARIH IS NULL");else if(mode==2)parts.Add("ICTARIH IS NOT NULL");t.DefaultView.RowFilter=string.Join(" AND ",parts);left.DataSource=t;}

}
